-- Review and run once in a Snowflake worksheet as ACCOUNTADMIN.
-- Contains only the public key. Never paste the private .p8 file into Snowflake.
-- CREATE USER intentionally fails if the name already exists; no replacement.
USE ROLE ACCOUNTADMIN;

CREATE USER CENSUS_COMPASS_SERVICE
    TYPE = SERVICE
    LOGIN_NAME = 'CENSUS_COMPASS_SERVICE'
    DEFAULT_ROLE = CENSUS_READER
    DEFAULT_SECONDARY_ROLES = ()
    DEFAULT_WAREHOUSE = COMPUTE_WH
    DEFAULT_NAMESPACE = 'US_OPEN_CENSUS_DATA_NEIGHBORHOOD_INSIGHTS_FREE_DATASET.PUBLIC'
    RSA_PUBLIC_KEY = ''
    COMMENT = 'Census Compass application service user';

GRANT ROLE CENSUS_READER TO USER CENSUS_COMPASS_SERVICE;

DESC USER CENSUS_COMPASS_SERVICE;
SHOW GRANTS TO USER CENSUS_COMPASS_SERVICE;
